// Bundles the game's live pixel scenes (src/themes/scenes/*.js) into one ES module the
// teaser can import, so Remotion draws the real animated art frame by frame.
// Generated file: src/teaser/live/scenes.generated.js (gitignored; rerun after scene edits).
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "../../..");
const scenesDir = path.join(root, "src/themes/scenes");
const out = path.resolve(__dirname, "../src/teaser/live/scenes.generated.js");

const files = [
  path.join(root, "src/themes/LiveScenes.js"),
  path.join(scenesDir, "PixelKit.js"),
  ...fs
    .readdirSync(scenesDir)
    .filter((f) => f.endsWith(".js") && f !== "PixelKit.js")
    .sort()
    .map((f) => path.join(scenesDir, f)),
];
const body = files
  .map((file) => {
    const code = fs
      .readFileSync(file, "utf8")
      .replace(/^if \(typeof module !== 'undefined'\).*$/gm, "");
    return `// ---- ${path.relative(root, file)}\n${code}`;
  })
  .join("\n");

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(
  out,
  `/* eslint-disable */\n// @ts-nocheck\n// Generated by scripts/bundle-live-scenes.cjs from the game's src/themes/scenes. Do not edit.\n` +
    `const performance = { now: () => 0 };\n` +
    `export const LiveScenes = (function () {\n${body}\nreturn LiveScenes;\n})();\n`,
);
console.log(`Bundled ${files.length - 2} live scenes into ${path.relative(root, out)}`);
